BEGIN READ ONLY;
SET LOCAL search_path=pg_catalog,public,extensions;
SET LOCAL timezone='UTC';
SET LOCAL statement_timeout='20s';
-- Metadata-only reuse of the pinned capture query for these same nine relations.
SELECT jsonb_build_object('diagnostic','scoped_provider_catalog_environment','search_path',current_setting('search_path'),'effective_schemas',current_schemas(true),'timezone',current_setting('TimeZone'));
SELECT jsonb_build_object('diagnostic','scoped_provider_catalog','catalog',to_jsonb(captured)) FROM (
WITH wanted(ns,nm) AS (VALUES ('public','notifications'),('public','operational_alert_events'),('public','push_outbox'),('public','accounting_invoice_deliveries'),('public','settlement_invoices'),('public','social_messages'),('public','social_conversation_participants'),('public','profiles'),('auth','users'))
SELECT clock_timestamp() observed_at,current_setting('server_version_num') server_version_num,n.nspname schema_name,c.relname name,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relreplident,c.reloptions,pg_get_userbyid(c.relowner) owner,c.relacl::text acl,
(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped) columns,
(SELECT jsonb_agg(jsonb_build_object('name',co.conname,'type',co.contype,'definition',pg_get_constraintdef(co.oid,true),'validated',co.convalidated,'deferrable',co.condeferrable,'deferred',co.condeferred) ORDER BY co.conname) FROM pg_constraint co WHERE co.conrelid=c.oid) constraints,
(SELECT jsonb_agg(jsonb_build_object('name',ci.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'primary',i.indisprimary) ORDER BY ci.relname) FROM pg_index i JOIN pg_class ci ON ci.oid=i.indexrelid WHERE i.indrelid=c.oid) indexes,
(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled,'internal',t.tgisinternal,'function',t.tgfoid::regprocedure::text,'function_md5',md5(pg_get_functiondef(t.tgfoid))) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal) triggers,
(SELECT jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END ORDER BY r) FROM unnest(p.polroles) r),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname) FROM pg_policy p WHERE p.polrelid=c.oid) policies
FROM wanted w JOIN pg_namespace n ON n.nspname=w.ns JOIN pg_class c ON c.relnamespace=n.oid AND c.relname=w.nm ORDER BY n.nspname,c.relname
) captured;
DO $$ BEGIN IF NOT EXISTS(SELECT p.oid FROM pg_proc p WHERE p.oid=to_regprocedure('auth.jwt()') AND md5(pg_get_functiondef(p.oid))='20054548ba2003f61a6bcb472175700b' AND pg_get_userbyid(p.proowner)='supabase_auth_admin' AND p.prosecdef=false AND p.proconfig IS NOT DISTINCT FROM NULL::text[] AND NOT EXISTS ((SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(p.proacl) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{=X/supabase_auth_admin,postgres=X/supabase_auth_admin,supabase_auth_admin=X/supabase_auth_admin,dashboard_user=X/supabase_auth_admin}'::aclitem[])) UNION ALL (SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{=X/supabase_auth_admin,postgres=X/supabase_auth_admin,supabase_auth_admin=X/supabase_auth_admin,dashboard_user=X/supabase_auth_admin}'::aclitem[]) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(p.proacl)))) THEN RAISE EXCEPTION 'provider function authority mismatch: auth.jwt()'; END IF; END $$;
