DO $$ BEGIN IF (SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=to_regclass('auth.users') AND a.attnum>0 AND NOT a.attisdropped) IS DISTINCT FROM '[{"name": "instance_id", "type": "uuid", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "id", "type": "uuid", "notnull": true, "identity": "", "generated": "", "default": null}, {"name": "aud", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "role", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "email", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "encrypted_password", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "email_confirmed_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "invited_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "confirmation_token", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "confirmation_sent_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "recovery_token", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "recovery_sent_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "email_change_token_new", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "email_change", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "email_change_sent_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "last_sign_in_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "raw_app_meta_data", "type": "jsonb", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "raw_user_meta_data", "type": "jsonb", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "is_super_admin", "type": "boolean", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "created_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "updated_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "phone", "type": "text", "notnull": false, "identity": "", "generated": "", "default": "NULL::character varying"}, {"name": "phone_confirmed_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "phone_change", "type": "text", "notnull": false, "identity": "", "generated": "", "default": "''''::character varying"}, {"name": "phone_change_token", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": "''''::character varying"}, {"name": "phone_change_sent_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "confirmed_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "s", "default": "LEAST(email_confirmed_at, phone_confirmed_at)"}, {"name": "email_change_token_current", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": "''''::character varying"}, {"name": "email_change_confirm_status", "type": "smallint", "notnull": false, "identity": "", "generated": "", "default": "0"}, {"name": "banned_until", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "reauthentication_token", "type": "character varying(255)", "notnull": false, "identity": "", "generated": "", "default": "''''::character varying"}, {"name": "reauthentication_sent_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "is_sso_user", "type": "boolean", "notnull": true, "identity": "", "generated": "", "default": "false"}, {"name": "deleted_at", "type": "timestamp with time zone", "notnull": false, "identity": "", "generated": "", "default": null}, {"name": "is_anonymous", "type": "boolean", "notnull": true, "identity": "", "generated": "", "default": "false"}]'::jsonb THEN RAISE EXCEPTION 'provider column/default mismatch: auth.users'; END IF; END $$;
DO $$ BEGIN IF (SELECT jsonb_agg(jsonb_build_object('name',co.conname,'type',co.contype,'definition',pg_get_constraintdef(co.oid,true),'validated',co.convalidated,'deferrable',co.condeferrable,'deferred',co.condeferred) ORDER BY co.conname) FROM pg_constraint co WHERE co.conrelid=to_regclass('auth.users')) IS DISTINCT FROM '[{"name": "users_email_change_confirm_status_check", "type": "c", "deferred": false, "validated": true, "deferrable": false, "definition": "CHECK (email_change_confirm_status >= 0 AND email_change_confirm_status <= 2)"}, {"name": "users_phone_key", "type": "u", "deferred": false, "validated": true, "deferrable": false, "definition": "UNIQUE (phone)"}, {"name": "users_pkey", "type": "p", "deferred": false, "validated": true, "deferrable": false, "definition": "PRIMARY KEY (id)"}]'::jsonb THEN RAISE EXCEPTION 'provider constraint mismatch: auth.users'; END IF; END $$;
DO $$ BEGIN IF (SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled,'internal',t.tgisinternal,'function',t.tgfoid::regprocedure::text,'function_md5',md5(pg_get_functiondef(t.tgfoid))) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=to_regclass('auth.users') AND NOT t.tgisinternal) IS DISTINCT FROM '[{"name": "on_auth_user_created", "enabled": "O", "function": "handle_new_user()", "internal": false, "definition": "CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user()", "function_md5": "e4ae3309ad1b563e22a532ce4718e4cf"}, {"name": "on_auth_user_created_diamonds", "enabled": "O", "function": "initialize_user_diamonds()", "internal": false, "definition": "CREATE TRIGGER on_auth_user_created_diamonds AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION initialize_user_diamonds()", "function_md5": "83bcbd3d49578ce1d27483f93f64a45b"}, {"name": "on_auth_user_created_wallet", "enabled": "O", "function": "handle_new_user_v2_create_wallet()", "internal": false, "definition": "CREATE TRIGGER on_auth_user_created_wallet AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user_v2_create_wallet()", "function_md5": "ac18912a92a37205a0b596ce13f42e9c"}]'::jsonb THEN RAISE EXCEPTION 'provider trigger mismatch: auth.users'; END IF; END $$;
