DO $$ BEGIN IF (SELECT jsonb_agg(jsonb_build_object('name',ci.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'primary',i.indisprimary) ORDER BY ci.relname) FROM pg_index i JOIN pg_class ci ON ci.oid=i.indexrelid WHERE i.indrelid=to_regclass('public.profiles')) IS DISTINCT FROM '[{"name": "idx_profiles_alias_trgm", "ready": true, "valid": true, "unique": false, "primary": false, "definition": "CREATE INDEX idx_profiles_alias_trgm ON public.profiles USING gin (lower(alias) gin_trgm_ops)"}, {"name": "idx_profiles_display_name_trgm", "ready": true, "valid": true, "unique": false, "primary": false, "definition": "CREATE INDEX idx_profiles_display_name_trgm ON public.profiles USING gin (lower(display_name) gin_trgm_ops)"}, {"name": "idx_profiles_farming_flagged", "ready": true, "valid": true, "unique": false, "primary": false, "definition": "CREATE INDEX idx_profiles_farming_flagged ON public.profiles USING btree (is_farming_flagged)"}, {"name": "idx_profiles_kyc_status", "ready": true, "valid": true, "unique": false, "primary": false, "definition": "CREATE INDEX idx_profiles_kyc_status ON public.profiles USING btree (kyc_status) WHERE (kyc_status = ANY (ARRAY[''PENDING''::text, ''APPROVED''::text, ''REJECTED''::text]))"}, {"name": "idx_profiles_referral_code", "ready": true, "valid": true, "unique": true, "primary": false, "definition": "CREATE UNIQUE INDEX idx_profiles_referral_code ON public.profiles USING btree (referral_code) WHERE (referral_code IS NOT NULL)"}, {"name": "idx_profiles_username_lower", "ready": true, "valid": true, "unique": true, "primary": false, "definition": "CREATE UNIQUE INDEX idx_profiles_username_lower ON public.profiles USING btree (lower(username)) WHERE (username IS NOT NULL)"}, {"name": "idx_profiles_username_trgm", "ready": true, "valid": true, "unique": false, "primary": false, "definition": "CREATE INDEX idx_profiles_username_trgm ON public.profiles USING gin (lower(us