DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.oid=to_regclass('public.profiles') AND pg_get_userbyid(c.relowner)='postgres' AND c.relrowsecurity=true AND c.relforcerowsecurity=false AND c.relreplident='d' AND NOT EXISTS ((SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(c.relacl) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{postgres=arwdDxtm/postgres,authenticated=adxtm/postgres,service_role=arwdDxtm/postgres}'::aclitem[])) UNION ALL (SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{postgres=arwdDxtm/postgres,authenticated=adxtm/postgres,service_role=arwdDxtm/postgres}'::aclitem[]) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(c.relacl)))) THEN RAISE EXCEPTION 'provider relation authority mismatch: public.profiles'; END IF; END $$;
