DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_namespace n WHERE n.nspname='auth' AND pg_get_userbyid(n.nspowner)='supabase_admin' AND NOT EXISTS ((SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(n.nspacl) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{supabase_admin=UC/supabase_admin,anon=U/supabase_admin,authenticated=U/supabase_admin,service_role=U/supabase_admin,supabase_auth_admin=UC/supabase_admin,dashboard_user=UC/supabase_admin,postgres=U/supabase_admin}'::aclitem[])) UNION ALL (SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{supabase_admin=UC/supabase_admin,anon=U/supabase_admin,authenticated=U/supabase_admin,service_role=U/supabase_admin,supabase_auth_admin=UC/supabase_admin,dashboard_user=UC/supabase_admin,postgres=U/supabase_admin}'::aclitem[]) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(n.nspacl)))) THEN RAISE EXCEPTION 'schema ACL mismatch: auth'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_namespace n WHERE n.nspname='extensions' AND pg_get_userbyid(n.nspowner)='postgres' AND NOT EXISTS ((SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(n.nspacl) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{postgres=UC/postgres,anon=U/postgres,authenticated=U/postgres,service_role=U/postgres,dashboard_user=UC/postgres}'::aclitem[])) UNION ALL (SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{postgres=UC/postgres,anon=U/postgres,authenticated=U/postgres,service_role=U/postgres,dashboard_user=UC/postgres}'::aclitem[]) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(n.nspacl)))) THEN RAISE EXCEPTION 'schema ACL mismatch: extensions'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_namespace n WHERE n.nspname='public' AND pg_get_userbyid(n.nspowner)='pg_database_owner' AND NOT EXISTS ((SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(n.nspacl) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{pg_database_owner=UC/pg_database_owner,=U/pg_database_owner,postgres=U/pg_database_owner,anon=U/pg_database_owner,authenticated=U/pg_database_owner,service_role=U/pg_database_owner}'::aclitem[])) UNION ALL (SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{pg_database_owner=UC/pg_database_owner,=U/pg_database_owner,postgres=U/pg_database_owner,anon=U/pg_database_owner,authenticated=U/pg_database_owner,service_role=U/pg_database_owner}'::aclitem[]) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(n.nspacl)))) THEN RAISE EXCEPTION 'schema ACL mismatch: public'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid WHERE s.seqrelid='public.operational_alert_events_id_seq'::regclass AND s.seqtypid='bigint'::regtype AND s.seqstart::text='1' AND s.seqincrement::text='1' AND s.seqmin::text='1' AND s.seqmax::text='9223372036854775807' AND s.seqcache::text='1' AND NOT s.seqcycle AND pg_get_userbyid(c.relowner)='postgres' AND NOT EXISTS ((SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(c.relacl) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{postgres=rwU/postgres,anon=rwU/postgres,authenticated=rwU/postgres,service_role=rwU/postgres}'::aclitem[])) UNION ALL (SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode('{postgres=rwU/postgres,anon=rwU/postgres,authenticated=rwU/postgres,service_role=rwU/postgres}'::aclitem[]) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(c.relacl)))) THEN RAISE EXCEPTION 'exact identity sequence mismatch'; END IF; END $$;
DO $$ BEGIN IF (SELECT jsonb_agg(jsonb_build_object('publication',pubname,'schema',schemaname,'table',tablename,'columns',attnames,'filter',rowfilter) ORDER BY pubname,schemaname,tablename) FROM pg_publication_tables WHERE schemaname='public' AND tablename='notifications') IS DISTINCT FROM '[{"table": "notifications", "filter": null, "schema": "public", "columns": ["id", "user_id", "type", "title", "message", "data", "read", "created_at", "updated_at", "is_read", "action_url", "metadata", "actor_id", "link", "read_at"], "publication": "supabase_realtime"}]'::jsonb THEN RAISE EXCEPTION 'notification publication metadata mismatch'; END IF; END $$;
DO $$ BEGIN IF (SELECT jsonb_agg(jsonb_build_object('name',e.extname,'schema',n.nspname,'version',e.extversion) ORDER BY e.extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname IN('pg_trgm','pgcrypto','uuid-ossp')) IS DISTINCT FROM '[{"name":"pg_trgm","schema":"public","version":"1.6"},{"name":"pgcrypto","schema":"extensions","version":"1.3"},{"name":"uuid-ossp","schema":"extensions","version":"1.1"}]'::jsonb THEN RAISE EXCEPTION 'required authentic extension version/schema mismatch'; END IF; END $$;
SELECT 'provider authority matched; no application or transport qualification claimed' AS stage;
COMMIT;
